// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io

// Made for @sableRaph's weekly creative challenge on Twitch (#WCCChallenge)
// https://www.twitch.tv/sableraph
// "Create a circle or a square in a new way"

const N_FRAMES = 750;

function setup() {
  createCanvas(500, 500);
  strokeWeight(1.25);
}

function draw() {
  background("#fffbe6");
  translate(width/2, height/2);
  rotate(PI/4);

  let t = frameCount%N_FRAMES;
  let transition = 1/20; // how long the transition is
  if (t < N_FRAMES*(1/2-transition)) t = 0;
  else if (t < N_FRAMES/2) t = easeOutElastic((t-N_FRAMES*(1/2-transition))/(transition*N_FRAMES));
  else if (t < N_FRAMES*(1-transition)) t = 1;
  else t = easeInElastic((N_FRAMES-t)/(transition*N_FRAMES));

  let paletteA = ["#f589a3", "#ef562f", "#fc8405", "#f9d531"];
  let paletteB = ["#abcd5e", "#14976b", "#2b67af", "#62b6de"];

  let theta0 = 3*PI*(frameCount%N_FRAMES/N_FRAMES);
  if (t < 1/2) theta0 = 3*PI-theta0;
  let nPoints = 60;
  let thetaStep = TAU/nPoints;
  let r = 133; // base radius for the shapes
  for (let i = 0; i < nPoints; i++) {
    let theta = i*thetaStep;

    let r1a = sqrt(2) * r * squareRadius(theta+theta0);
    let r1b = r * (1+sqrt(2))/2;
    let r1 = r1a*(1-t) + r1b*t;
    let x1 = r1*cos(theta);
    let y1 = r1*sin(theta);

    let r2a = r;
    let r2b = r1b * squareRadius(theta+theta0);
    let r2 = r2a*(1-t) + r2b*t;
    let x2 = r2*cos(theta);
    let y2 = r2*sin(theta);

    let r3a = r * squareRadius(theta+theta0);
    let r3b = r1b / sqrt(2);
    let r3 = r3a*(1-t) + r3b*t;
    let x3 = r3*cos(theta);
    let y3 = r3*sin(theta);

    stroke(5);
    line(x1, y1, x2, y2);
    line(x2, y2, x3, y3);

    let colA = color(paletteA[i%paletteA.length]);
    let colB = color(paletteB[i%paletteB.length]);
    let col = lerpColor(colA, colB, t);
    fill(col);
    noStroke();
    circle(x2, y2, 10);
  }
}

// reference: https://math.stackexchange.com/questions/41940/is-there-an-equation-to-describe-regular-polygons#41954
function squareRadius(theta) {
  return cos(PI/4)/cos(((theta)%(TAU/4)) - PI/4);
}

// adapted from easings.net
function easeOutElastic(x) {
  const c4 = (2 * Math.PI) / 3;
  return x === 0 ? 0 : x === 1 ? 1 : Math.pow(2, -10 * x) * Math.sin((x * 10 - 0.75) * c4) + 1;
}

function easeInElastic(x) {
  var c4 = (2 * Math.PI) / 3;
  return x === 0 ? 0 : x === 1 ? 1 : -Math.pow(2, 10 * x - 10) * Math.sin((x * 10 - 10.75) * c4);
}
